var t=`0791-fish-cari-coco`;var n=`world-0791`;var s=`SC`;var o=`eastern-africa`;var a=4;var r=41;var l={en:`Fish Cari Coco`,ua:`Рибне кокосове карі`};var g={en:`Fish Cari Coco is a Seychelles classic prepared with yellow onion, garlic, tilapia, coconut milk. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Рибне кокосове карі, страва кухні країни Сейшельські Острови зі складниками: жовта цибуля, часник, тилапія, кокосове молоко. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var c=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,190,`g`],[`garlic`,4,`clove`],[`curry-powder`,12,`g`],[`sunflower-oil`,45,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 27 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 27 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:27,i:[[`tilapia`,800,`g`],[`coconut-milk`,470,`ml`],[`tomato`,300,`g`],[`ground-turmeric`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,2,`pcs`],[`cilantro`,18,`g`]]}];var d={slug:t,id:n,country:`SC`,region:o,servings:4,minutes:41,title:l,text:g,steps:c};export{s as country,d as default,n as id,r as minutes,o as region,a as servings,t as slug,c as steps,g as text,l as title};